                            'objective' => 'Express agreement, partial agreement, and disagreement without offending.',
                            'xp' => 30, 'minutes' => 15,
                            'sections' => [
                                ['type' => 'intro', 'title' => 'The art of saying no politely', 'body' => "In meetings and conversations, you must often express views that differ from others. B2 speakers don\'t simply say \"You\'re wrong.\" Instead, they use sophisticated strategies:\n\n- Acknowledge the other person's point (partial agreement)\n- Provide a contrasting viewpoint\n- Suggest alternatives\n- Close diplomatically\n\nThese techniques preserve relationships and encourage thoughtful discussion."],
                                ['type' => 'explanation', 'title' => 'Strategies and phrases', 'body' => "**Full agreement:**\n- I completely agree (with you).\n- That's an excellent point.\n- I couldn't agree more.\n\n**Partial agreement (useful for debate):**\n- You have a point, but...\n- I see what you mean. However,...\n- That's true to some extent, yet...\n- I agree in principle, although...\n\n**Polite disagreement:**\n- I'm afraid I have to disagree.\n- I don\'t quite see it that way.\n- With respect, I think...\n- I appreciate your view, but I'd argue that...\n\n**Strong disagreement (less frequent; use when important):**\n- I fundamentally disagree.\n- I must respectfully challenge that.\n\n**Offering alternatives:**\n- What if we considered...?\n- Have you thought about...?\n- Another way to look at it is...\n\nNotice the pattern: validate → contrast → propose. This maintains harmony.", 'body_id' => 'Partial agreement memungkinkan debat konstruktif. Selalu validasi poin lawan sebelum tidak setuju.'],
                                ['type' => 'examples', 'title' => 'Examples', 'meta' => ['items' => [
                                    ['en' => 'A: "We should cut costs immediately." B: "I see your concern, but rushing could harm quality. What if we phased the reductions?"', 'id' => 'A: "Kita harus potong biaya sekarang." B: "Saya memahami kekhawatiran Anda, tapi terburu-buru bisa merusak kualitas."'],
                                    ['en' => 'A: "Remote work decreases productivity." B: "You\'re right that collaboration is harder online, yet data shows productivity often rises with flexibility."', 'id' => 'Anda benar bahwa kolaborasi lebih sulit online, namun data menunjukkan produktivitas sering meningkat.'],
                                    ['en' => 'A: "We don\'t need this feature." B: "I appreciate your viewpoint. However, customer feedback indicates strong demand for it."', 'id' => 'Saya menghargai sudut pandang Anda. Namun umpan balik pelanggan menunjukkan permintaan kuat.'],
                                ]]],
                                ['type' => 'vocabulary', 'title' => 'Debate phrases', 'meta' => ['words' => [
                                    ['word' => 'nevertheless', 'ipa' => '/nev-er-the-less/', 'meaning_id' => 'meskipun demikian; tetap saja', 'example' => 'I agree it\'s expensive. Nevertheless, the long-term benefit justifies the cost.'],
                                    ['word' => 'compelling', 'ipa' => '/kəm-pel-ing/', 'meaning_id' => 'menarik; meyakinkan', 'example' => 'That\'s a compelling argument, but we must consider risks.'],
                                    ['word' => 'counterargument', 'ipa' => '/coun-ter-ar-gue-ment/', 'meaning_id' => 'sanggahan; argumen tandingan', 'example' => 'His counterargument made us reconsider our position.'],
                                ]]],
                                ['type' => 'dialogue', 'title' => 'Meeting discussion', 'meta' => ['lines' => [
                                    ['speaker' => 'Manager', 'text' => 'I think we should drop the secondary product line to focus resources.'],
                                    ['speaker' => 'Team lead', 'text' => 'I understand the appeal of streamlining. However, that line generates 20% of revenue. What if we optimized operations instead of cutting it?'],
                                    ['speaker' => 'Manager', 'text' => 'An interesting point. What kind of optimization did you have in mind?'],
                                    ['speaker' => 'Team lead', 'text' => 'Automation could cut costs by 30%. We\'d keep revenue and reduce headcount.'],
                                ]]],
                            ],
                            'exercises' => [[
                                'title' => 'Practice: Diplomatic Disagreement',
                                'xp' => 15, 'pick' => 0,
                                'questions' => [
                                    ['type' => 'multiple_choice', 'prompt' => 'A colleague says the project timeline is unrealistic. Which response is most diplomatic?', 'difficulty' => 'medium',
                                        'explanation' => 'Diplomatic responses acknowledge the concern, then offer reasoning or alternatives.', 'explanation_id' => 'Respons diplomatik mengakui kekhawatiran, lalu tawarkan alasan atau alternatif.',
                                        'options' => [['I appreciate your concern. I believe we can meet it if we prioritize critical tasks.', true], ['No, the timeline is fine.', false], ['Your timeline would take too long.', false], ['Stop complaining.', false]]],
                                    ['type' => 'fill_blank', 'prompt' => 'You ___ a point, but I think we should consider the customer feedback first.', 'config' => ['accepted' => ['have', 'make']]],
                                    ['type' => 'true_false', 'prompt' => 'Saying "You\'re wrong" is appropriate in professional debates.', 'config' => ['correct' => false]],
                                    ['type' => 'rearrange', 'prompt' => 'Arrange a diplomatically disagreeing sentence.', 'config' => ['order' => ['I', 'appreciate', 'your', 'perspective,', 'yet', 'I', 'think', 'there', 'is', 'more', 'to', 'consider']]],
                                    ['type' => 'fill_blank', 'prompt' => 'Complete the diplomatic phrase: "I see your point, but I\'m not sure I ___ with the timeline." (setuju)', 'config' => ['accepted' => ['agree']],
                                        'explanation' => 'Softening + "I\'m not sure I agree" keeps disagreement polite.'],
                                    ['type' => 'multiple_choice', 'prompt' => 'Which phrase introduces an alternative viewpoint most diplomatically?', 'difficulty' => 'medium',
                                        'options' => [['I appreciate your point. Another way to look at it is...', true], ['You are completely wrong.', false], ['That makes no sense.', false], ['Let me explain what you missed.', false]]],
                                ],
                            ]],
                        ],
                        [
                            'title' => 'Expressing Certainty, Speculation & Possibility',
                            'objective' => 'Use modal phrases to express levels of confidence about present and past events.',
                            'xp' => 30, 'minutes' => 15,
                            'prerequisites' => ['Agreeing & Disagreeing Diplomatically'],
                            'sections' => [
                                ['type' => 'intro', 'title' => 'Beyond "maybe" and "probably"', 'body' => "B2 speakers need nuanced ways to express confidence:\n\n\"The email is definitely in his inbox.\" (near-certain)\n\"He must be in a meeting.\" (logical deduction)\n\"The data could have been corrupted.\" (speculation about past)\n\"We're bound to face delays.\" (expectation)\n\nThese structures help you hedge claims, report deductions, and discuss unlikely or impossible scenarios with precision."],
                                ['type' => 'explanation', 'title' => 'Modal phrases for certainty & possibility', 'body' => "**Certainty (present):**\n- It's certain/sure/definite that... (100%)\n- He must be here. / It's bound to happen. (logical deduction, ~95%)\n- It will definitely happen. / She's almost certainly right. (~95%)\n\n**Possibility (present):**\n- It's possible/likely that... (~70-80%)\n- He might be in a meeting. / He could be sick. (~30-50%)\n- He may arrive soon. (~50-70%, more formal than might)\n\n**Certainty (past):**\n- Must have + past participle (deduction): She must have left early. (She probably did; I saw her go.)\n- Can't have + past participle (impossible): He can't have stolen it. (It's impossible; he wasn't there.)\n- Might have / could have / may have + past participle (speculation): The server might have crashed. (Possible, but I'm not sure.)\n\n**Key distinction:**\n- Must have = high probability based on evidence\n- Might have = speculation; I'm unsure\n- Can't have = logical impossibility", 'body_id' => 'Must have = kemungkinan tinggi. Might have = spekulasi. Can\'t have = tidak mungkin.'],
                                ['type' => 'examples', 'title' => 'Examples', 'meta' => ['items' => [
                                    ['en' => 'He must have missed the memo. (I didn\'t see him at the meeting, so he probably didn\'t know.)', 'id' => 'Dia pasti melewatkan memo itu. (Saya tidak melihatnya di rapat.)'],
                                    ['en' => 'She can\'t have said that. (It\'s impossible; she\'s not that kind of person.)', 'id' => 'Dia tidak mungkin mengatakan itu. (Sangat tidak mungkin.)'],
                                    ['en' => 'The system could have been updated overnight. (Speculation; I\'m not certain.)', 'id' => 'Sistem mungkin telah diperbarui semalam.'],
                                    ['en' => 'We\'re bound to encounter problems. (It\'s nearly certain; based on experience.)', 'id' => 'Kita pasti akan menghadapi masalah.'],
                                ]]],
                                ['type' => 'vocabulary', 'title' => 'Certainty expressions', 'meta' => ['words' => [
                                    ['word' => 'deduce', 'ipa' => '/di-doos/', 'meaning_id' => 'menyimpulkan; menjabarkan', 'example' => 'From the evidence, I deduced that she was guilty.'],
                                    ['word' => 'speculate', 'ipa' => '/spek-yuh-layt/', 'meaning_id' => 'berspekulasi; menduga', 'example' => 'We can only speculate about her reasons for resigning.'],
                                    ['word' => 'feasible', 'ipa' => '/fee-zuh-bul/', 'meaning_id' => 'dapat dilaksanakan; layak', 'example' => 'The timeline is feasible if we allocate more resources.'],
                                ]]],
                                ['type' => 'tip', 'title' => 'Must have vs. should have', 'body' => "- **Must have** = deduction about the past (I didn't see him leave, but he must have gone home.)\n- **Should have** = regret or expectation unfulfilled (You should have told me earlier!)\n\nNever confuse them in B2 contexts. Must have is neutral; should have expresses blame or missed opportunity."],
                            ],
                            'exercises' => [[
                                'title' => 'Practice: Expressing Certainty & Speculation',
                                'xp' => 15, 'pick' => 0,
                                'questions' => [
                                    ['type' => 'multiple_choice', 'prompt' => 'The supplier hasn\'t answered my calls. He ___ received my messages.', 'difficulty' => 'medium',
                                        'explanation' => 'Must have indicates logical deduction about the past.', 'explanation_id' => 'Must have menunjukkan deduksi logis tentang masa lalu.',
                                        'options' => [['must have', true], ['might receive', false], ['will receive', false], ['could not', false]]],
                                    ['type' => 'fill_blank', 'prompt' => 'That result ___ be correct. We double-checked the data twice.', 'config' => ['accepted' => ['can\'t', 'cannot']]],
                                    ['type' => 'true_false', 'prompt' => 'The phrase "She could have done it better" expresses near-certain deduction about the past.', 'config' => ['correct' => false]],
                                    ['type' => 'rearrange', 'prompt' => 'Arrange a sentence with modal + past participle.', 'config' => ['order' => ['You', 'must', 'have', 'forgotten', 'the', 'password']]],
                                    ['type' => 'translation', 'prompt' => 'Translate: "Dia mungkin telah meninggalkan kantor lebih awal hari ini."', 'config' => ['accepted' => ['She might have left the office early today', 'He could have left early today']]],
                                    ['type' => 'multiple_choice', 'prompt' => 'Which sentence correctly expresses near-impossibility in the past?', 'difficulty' => 'medium',
                                        'options' => [['He can\'t have stolen the money; he wasn\'t in the building.', true], ['He must have stolen the money.', false], ['He might have stolen the money.', false], ['He could not steal the money.', false]]],
                                ],
                            ]],
