                [
                    'title' => 'Job Interviews & Professional Conversations',
                    'description' => 'Answer behavioral questions, discuss strengths and experience, and handle tricky situations.',
                    'lessons' => [
                        [
                            'title' => 'Interview Techniques: Strengths, Experience & Behavior',
                            'objective' => 'Answer common interview questions with clarity, evidence, and confidence.',
                            'xp' => 30, 'minutes' => 15,
                            'sections' => [
                                ['type' => 'intro', 'title' => 'Beyond "Tell me about yourself"', 'body' => "Job interviews at B2 level require structured answers:\n\nInterviewer: \"Describe a time you led a team through a crisis.\"\nWeak answer: \"I'm a good leader.\"\nStrong answer: \"In 2021, our team faced a server outage during peak sales. I coordinated with IT, communicated hourly updates to stakeholders, and reorganized our workflow to minimize losses.\"\n\nB2 answers use specific examples, quantified results, and professional language."],
                                ['type' => 'explanation', 'title' => 'The STAR method: Structure for behavioral questions', 'body' => "**Situation:** Set the context briefly.\n- \"I was working as a project manager on a tight deadline...\"\n\n**Task:** What was your responsibility?\n- \"My role was to keep the team coordinated and deliver on time.\"\n\n**Action:** What did you specifically do?\n- \"I reorganized the workflow, held daily stand-ups, and escalated blockers immediately.\"\n\n**Result:** What happened? Use numbers if possible.\n- \"We delivered 2 weeks early. Customer satisfaction rose to 95%.\"", 'body_id' => 'STAR method: Situation, Task, Action, Result. Selalu gunakan contoh spesifik dan angka.'],
                                ['type' => 'examples', 'title' => 'Full STAR answer example', 'meta' => ['items' => [
                                    ['en' => 'Q: \"Describe a time you exceeded expectations.\" A: \"I was tasked with improving report efficiency. Instead of automating just one report, I analyzed all 15 and created a unified template system. This reduced generation time from 8 hours to 2 hours per week—a 75% gain.\"', 'id' => 'Saya ditugaskan untuk meningkatkan efisiensi laporan. Saya membuat sistem template terpadu, mengurangi waktu dari 8 jam menjadi 2 jam per minggu.'],
                                    ['en' => 'Q: \"Tell me about a challenge you faced.\" A: \"Our team was understaffed during a product launch. I coordinated with the marketing team to shift timelines, managed stakeholder expectations weekly, and successfully launched without burnout.\"', 'id' => 'Tim kami kekurangan staf. Saya mengoordinasikan dengan tim marketing untuk mengubah jadwal dan berhasil meluncurkan produk.'],
