                                    ['word' => 'stakeholder', 'ipa' => '/stayk-hol-der/', 'meaning_id' => 'pemangku kepentingan', 'example' => 'I briefed key stakeholders weekly on project progress.'],
                                    ['word' => 'initiative', 'ipa' => '/i-nish-uh-tiv/', 'meaning_id' => 'inisiatif; prakarsa', 'example' => 'I led the cost-reduction initiative and saved the company $200K.'],
                                    ['word' => 'proactive', 'ipa' => '/pro-ak-tiv/', 'meaning_id' => 'proaktif; mengambil langkah awal', 'example' => 'A proactive approach means solving problems before they escalate.'],
                                ]]],
                                ['type' => 'dialogue', 'title' => 'Mock interview', 'meta' => ['lines' => [
                                    ['speaker' => 'Interviewer', 'text' => 'What would you say is your biggest weakness?'],
                                    ['speaker' => 'Candidate', 'text' => 'I used to struggle with delegation—I wanted to control every detail. Through coaching, I learned to trust my team. Now I delegate strategically, which freed me to focus on strategy.'],
                                    ['speaker' => 'Interviewer', 'text' => 'That\'s a thoughtful answer. Can you give me an example?'],
