                                'xp' => 15, 'pick' => 0,
                                'questions' => [
                                    ['type' => 'multiple_choice', 'prompt' => 'What makes a strong interview answer about a challenge?', 'difficulty' => 'medium',
                                        'explanation' => 'Strong answers use specific examples and show how you contributed to a solution.', 'explanation_id' => 'Jawaban kuat menggunakan contoh spesifik dan menunjukkan kontribusi Anda.',
                                        'options' => [['It describes a real situation, your actions, and a measurable outcome.', true], ['It shows how your boss failed.', false], ['It complains about the company.', false], ['It is vague and general.', false]]],
