                                    ['type' => 'rearrange', 'prompt' => 'Arrange a professional response opening.', 'config' => ['order' => ['That\'s', 'an', 'excellent', 'question.', 'Let', 'me', 'give', 'you', 'a', 'concrete', 'example']]],
