                [
                    'title' => 'Formal Email & Complaint Handling',
                    'description' => 'Write professional complaints, requests, and formal correspondence with tact and clarity.',
                    'lessons' => [
                        [
                            'title' => 'Writing Formal Complaints & Requests',
                            'objective' => 'Compose complaints and requests that are assertive yet diplomatic.',
                            'xp' => 30, 'minutes' => 15,
                            'sections' => [
                                ['type' => 'intro', 'title' => 'Professional complaints: structure and tone', 'body' => "Informal complaint: \"Your service is terrible. Fix it NOW!\"\nFormal complaint (B2): \"I have experienced recurring issues with your support response time. While I value our partnership, the average resolution time of 10 days has impacted my operations. I would appreciate a resolution within 48 hours, or we may need to reassess our contract.\"\n\nThe B2 approach: state facts, show impact, make a clear request, suggest consequences calmly."],
                                ['type' => 'explanation', 'title' => 'Complaint email structure', 'body' => "**Subject line:** Clear and professional\n- Subject: Urgent: Unresolved Issue with Account #12345\n\n**Opening:** Polite, reference the relationship\n- I appreciate our long-standing partnership, but I must bring an issue to your attention.\n- I am writing regarding a concern about our recent transaction.\n\n**Problem:** State facts, not emotions\n- ✓ The invoice was sent on [date], but the agreed payment terms were 30 days.\n- ✗ You sent an invoice too early and it\'s completely unreasonable!\n\n**Impact:** Show business effect\n- This delay has disrupted our budget cycle and caused my team additional work.\n\n**Request:** Clear, specific, reasonable\n- I request that you reissue the invoice with corrected terms by [date].\n- Could you provide an explanation and a corrected version?\n\n**Closing:** Professional, not threatening (unless final)\n- I look forward to resolving this matter cooperatively.\n- If this is not resolved by [date], I will need to escalate to [authority].\n\n**Sign-off:** Formal\n- Best regards / Sincerely / Yours professionally", 'body_id' => 'Email resmi: pembukaan sopan, fakta, dampak, permintaan jelas, penutup profesional.'],
                                ['type' => 'examples', 'title' => 'Full complaint email example', 'meta' => ['items' => [
                                    ['en' => 'Subject: Urgent: Missing Documentation for Project Delivery\n\nDear [Name],\n\nI am writing to address a critical issue affecting our current project. As agreed in our contract, your team was to provide technical specifications by March 15. These documents are now 10 days overdue, and our development team cannot proceed without them.\n\nThis delay risks our project completion date and may incur additional costs. I request that you prioritize delivery of these documents by March 28, or we will need to discuss contingency plans.\n\nPlease confirm receipt of this email and provide a timeline for delivery.\n\nBest regards,\n[Your name]', 'id' => 'Surat keluhan resmi dengan struktur jelas: masalah, dampak, permintaan, tenggat waktu.'],
                                ]]],
                                ['type' => 'vocabulary', 'title' => 'Formal email phrases', 'meta' => ['words' => [
                                    ['word' => 'escalate', 'ipa' => '/es-kuh-layt/', 'meaning_id' => 'meningkatkan; mengangkat', 'example' => 'If the issue is not resolved, I will escalate to management.'],
                                    ['word' => 'rectify', 'ipa' => '/rek-tuh-fy/', 'meaning_id' => 'memperbaiki; mengoreksi', 'example' => 'Please rectify the billing error immediately.'],
                                    ['word' => 'attest', 'ipa' => '/uh-test/', 'meaning_id' => 'membuktikan; menyaksikan', 'example' => 'I can attest that the contract terms were misunderstood.'],
                                ]]],
                                ['type' => 'tip', 'title' => 'Tone in formal complaints', 'body' => "✓ Controlled, factual, professional\n✓ Shows respect even when disappointed\n✓ Offers solutions, not just problems\n✗ All caps or multiple exclamation marks\n✗ Personal attacks or insults\n✗ Threats without evidence or authority\n\nGoal: Make it easy for the recipient to help you."],
                            ],
                            'exercises' => [[
                                'title' => 'Practice: Formal Email Writing',
                                'xp' => 15, 'pick' => 0,
                                'questions' => [
                                    ['type' => 'multiple_choice', 'prompt' => 'Which opening is most appropriate for a formal complaint?', 'difficulty' => 'medium',
                                        'explanation' => 'Professional openings acknowledge the relationship before raising the issue.', 'explanation_id' => 'Pembukaan profesional mengakui hubungan sebelum mengangkat masalah.',
                                        'options' => [['I appreciate our partnership, but I must bring an issue to your attention.', true], ['Your service is awful and unacceptable!', false], ['I hate dealing with your company.', false], ['Fix this immediately or else.', false]]],
