                                    ['type' => 'true_false', 'prompt' => 'Using all caps and multiple exclamation marks strengthens a formal complaint.', 'config' => ['correct' => false]],
                                    ['type' => 'rearrange', 'prompt' => 'Arrange a professional problem statement.', 'config' => ['order' => ['The', 'invoice', 'was', 'issued', 'in', 'violation', 'of', 'the', 'agreed', 'payment', 'terms']]],
                                    ['type' => 'translation', 'prompt' => 'Translate to English: "Saya menantikan balasan Anda." (formal closing)', 'config' => ['accepted' => ['I look forward to your reply', 'I look forward to your response', 'I am looking forward to your reply', 'I am looking forward to your response']],
                                        'explanation' => '"I look forward to your reply" is the standard formal closing.'],
                                    ['type' => 'multiple_choice', 'prompt' => 'What should be included in a formal complaint email request section?', 'difficulty' => 'medium',
                                        'options' => [['Clear, specific actions and a reasonable deadline.', true], ['Vague wishes and complaints.', false], ['Personal insults.', false], ['Threats without a deadline.', false]]],
